CREATE TABLE vehicles (\n    id SERIAL PRIMARY KEY,\n    name VARCHAR(100) NOT NULL,\n    model VARCHAR(100),\n    battery_type VARCHAR(50),\n    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE battery_history (\n    id SERIAL PRIMARY KEY,\n    vehicle_id INT REFERENCES vehicles(id),\n    charge_level DECIMAL(5, 2),\n    timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE routes (\n    id SERIAL PRIMARY KEY,\n    name VARCHAR(100) NOT NULL,\n    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE route_waypoints (\n    id SERIAL PRIMARY KEY,\n    route_id INT REFERENCES routes(id),\n    latitude DECIMAL(9, 6),\n    longitude DECIMAL(9, 6),\n    sequence INT\n);\n\nCREATE TABLE charging_stations (\n    id SERIAL PRIMARY KEY,\n    location VARCHAR(255),\n    capacity INT\n);\n\nCREATE TABLE charging_sessions (\n    id SERIAL PRIMARY KEY,\n    vehicle_id INT REFERENCES vehicles(id),\n    station_id INT REFERENCES charging_stations(id),\n    start_time TIMESTAMP,\n    end_time TIMESTAMP\n);\n\nCREATE TABLE gps_tracking (\n    id SERIAL PRIMARY KEY,\n    vehicle_id INT REFERENCES vehicles(id),\n    latitude DECIMAL(9, 6),\n    longitude DECIMAL(9, 6),\n    timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE geofences (\n    id SERIAL PRIMARY KEY,\n    name VARCHAR(100),\n    coordinates TEXT\n);\n\nCREATE TABLE alerts (\n    id SERIAL PRIMARY KEY,\n    vehicle_id INT REFERENCES vehicles(id),\n    message TEXT,\n    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE route_assignments (\n    id SERIAL PRIMARY KEY,\n    route_id INT REFERENCES routes(id),\n    vehicle_id INT REFERENCES vehicles(id)\n);\n\nCREATE TABLE maintenance_log (\n    id SERIAL PRIMARY KEY,\n    vehicle_id INT REFERENCES vehicles(id),\n    description TEXT,\n    date TIMESTAMP DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE soh_predictions (\n    id SERIAL PRIMARY KEY,\n    vehicle_id INT REFERENCES vehicles(id),\n    predicted_soh DECIMAL(5, 2),\n    prediction_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE consumption_profiles (\n    id SERIAL PRIMARY KEY,\n    vehicle_id INT REFERENCES vehicles(id),\n    consumption_rate DECIMAL(5, 2),\n    recorded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE kpi_snapshots (\n    id SERIAL PRIMARY KEY,\n    vehicle_id INT REFERENCES vehicles(id),\n    kpi_value DECIMAL(10, 2),\n    snapshot_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE INDEX idx_vehicle_id ON battery_history(vehicle_id);\n\n-- Sample Data\nINSERT INTO vehicles (name, model, battery_type) VALUES ('Vehicle 1', 'Model A', 'Lithium-Ion');\n\n-- Grant permissions\nGRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO role_name;